import {normalizeRoom} from './details.mjs?v=cad18';
import {roomVertices,validatePolygon,calibratePlan,effectiveOpenings} from './room-pro.mjs?v=cad18';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installRoomPro({getProject,commit,scene,toast}){const button=document.createElement('button');button.className='wide-button';button.id='room-pro-open';button.textContent='Контур, проёмы и коммуникации ↗';document.querySelector('#room-pane').prepend(button);const dialog=document.createElement('dialog');dialog.className='pro-dialog';dialog.id='room-pro-dialog';document.body.append(dialog);let draft,points=[],planCanvas,planImage;
const field=(k,label,value,type='number')=>`<label>${label}<input data-field="${k}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="any"':''}></label>`;
function collection(key,label,items,fields,options=''){return `<h3>${label}</h3><div data-collection="${key}">${items.map((o,i)=>`<div class="pro-card" data-item="${i}"><div class="pro-row">${options?`<label>Тип<select data-field="type">${options.split('|').map(t=>{const [v,l]=t.split(':');return `<option value="${v}" ${o.type===v?'selected':''}>${l}</option>`;}).join('')}</select></label>`:''}${fields.map(([k,l,t])=>field(k,l,k==='wallIndex'?o[k]+1:o[k],t)).join('')}</div><button class="danger" data-remove="${key}:${i}">Удалить</button></div>`).join('')}</div><button data-add="${key}">+ Добавить</button>`;}
function render(){if(!draft)return;dialog.innerHTML=`<button class="pro-close" data-close>Закрыть</button><h2>Геометрия помещения</h2><p>Координаты в миллиметрах. Стены нумеруются по порядку вершин. Изменения применяются вместе и отменяются одной командой.</p><div class="pro-actions"><button data-shape="rectangle">Прямоугольник</button><button data-shape="l">Г-образная комната</button></div><label>Контур: одна вершина X, Z на строку<textarea id="room-vertices">${roomVertices(draft).map(p=>p.x+', '+p.z).join('\n')}</textarea></label><div class="pro-actions"><button data-preview>Проверить контур</button></div><div id="polygon-preview"></div><h3>Отделка каждой стены</h3><div id="wall-finishes">${roomVertices(draft).map((_,i)=>{const f=draft.wallFinishes.find(f=>f.wallIndex===i)||{color:draft.wall,material:'inherit'};return `<div class="pro-row" data-wall="${i}"><strong>Стена ${i+1}</strong><label>Материал<select data-wall-material>${['inherit:Общая отделка','paint:Краска','plaster:Штукатурка','oak:Дерево','marble:Мрамор','concrete:Бетон'].map(t=>{const [v,l]=t.split(':');return `<option value="${v}" ${f.material===v?'selected':''}>${l}</option>`;}).join('')}</select></label><label>Цвет<input data-wall-color type="color" value="${f.color}"></label><label>Шероховатость<input data-wall-rough type="number" min="0.05" max="1" step="0.05" value="${f.roughness??.5}"></label><label>Масштаб текстуры<input data-wall-scale type="number" min="0.1" max="5" step="0.1" value="${f.scale??1}"></label></div>`;}).join('')}</div>${collection('openings','Проёмы',draft.openings,[['wallIndex','Номер стены'],['offset','От начала стены'],['width','Ширина'],['height','Высота'],['sill','Низ от пола'],['open','Открывание, %']],'window:Окно|door:Дверь|opening:Проход')}${collection('obstacles','Колонны и выступы',draft.obstacles,[['x','X'],['z','Z'],['width','Ширина'],['depth','Глубина'],['height','Высота'],['rotation','Поворот °']],'column:Колонна|obstacle:Выступ')}${collection('services','Коммуникации',draft.services,[['label','Подпись','text'],['x','X'],['y','Высота Y'],['z','Z'],['width','Ширина'],['height','Высота элемента'],['depth','Глубина']],'socket:Розетка|pipe:Труба|vent:Вентиляция|connection:Зона подключения')}<h3>План помещения</h3><p>Загрузите PNG, JPEG или WebP. Выберите две точки на изображении и укажите реальное расстояние между ними.</p><input id="plan-upload" type="file" accept="image/png,image/jpeg,image/webp"><div class="pro-row">${field('distance','Расстояние между точками, мм',3000)}${field('offsetX','Центр плана X',draft.planImage?.offsetX||0)}${field('offsetZ','Центр плана Z',draft.planImage?.offsetZ||0)}${field('rotation','Поворот плана °',draft.planImage?.rotation||0)}${field('opacity','Непрозрачность 0.05–0.9',draft.planImage?.opacity??.45)}</div><div class="pro-actions"><button id="plan-calibrate">Применить масштаб</button><button id="plan-clear">Убрать план</button></div><canvas id="plan-canvas" width="700" height="400"></canvas><p id="plan-status"></p><p class="pro-error" id="room-pro-error"></p><div class="pro-actions"><button id="room-pro-apply">Применить помещение</button><button data-close>Отмена</button></div>`;dialog.querySelectorAll('[data-wall]').forEach(row=>{const select=row.querySelector('select');const sync=()=>row.querySelectorAll('input').forEach(input=>input.disabled=select.value==='inherit');select.addEventListener('change',sync);sync();});planCanvas=dialog.querySelector('#plan-canvas');if(draft.planImage)loadImage(draft.planImage.src);preview();}
function read(){const v=parseVertices();if(validatePolygon(v).valid)draft.vertices=v;for(const key of ['openings','obstacles','services'])dialog.querySelectorAll(`[data-collection="${key}"] [data-item]`).forEach(el=>{const o=draft[key][+el.dataset.item];el.querySelectorAll('[data-field]').forEach(input=>o[input.dataset.field]=input.type==='number'?Number(input.value)-(input.dataset.field==='wallIndex'?1:0):input.value);});draft.wallFinishes=[...dialog.querySelectorAll('[data-wall]')].filter(el=>el.querySelector('select').value!=='inherit').map(el=>({wallIndex:+el.dataset.wall,material:el.querySelector('select').value,color:el.querySelector('input').value,roughness:+el.querySelector('[data-wall-rough]').value,scale:+el.querySelector('[data-wall-scale]').value}));}
function parseVertices(){return dialog.querySelector('#room-vertices').value.trim().split('\n').map(s=>{const a=s.trim().split(/[,;\s]+/).map(Number);return {x:a[0],z:a[1]};});}
function preview(){const v=parseVertices(),result=validatePolygon(v);dialog.querySelector('#room-pro-error').textContent=result.errors.join('\n');if(!result.valid)return false;draft.vertices=v;const minX=Math.min(...v.map(p=>p.x)),minZ=Math.min(...v.map(p=>p.z)),w=Math.max(...v.map(p=>p.x))-minX,h=Math.max(...v.map(p=>p.z))-minZ;dialog.querySelector('#polygon-preview').innerHTML=`<svg viewBox="${minX-200} ${minZ-200} ${w+400} ${h+400}" height="180" width="100%"><polygon points="${v.map(p=>p.x+','+p.z).join(' ')}" fill="#dfe8cf" stroke="#667d4b" stroke-width="25"/>${v.map((p,i)=>`<text x="${p.x}" y="${p.z}" font-size="150">${i+1}</text>`).join('')}</svg>`;return true;}
function loadImage(src){planImage=new Image();planImage.onload=drawPlan;planImage.onerror=()=>toast('Не удалось прочитать изображение плана');planImage.src=src;}
function drawPlan(){if(!planImage)return;planCanvas.height=Math.round(planCanvas.width*planImage.height/planImage.width);const ctx=planCanvas.getContext('2d');ctx.drawImage(planImage,0,0,planCanvas.width,planCanvas.height);ctx.fillStyle='#df6a38';for(const p of points){ctx.beginPath();ctx.arc(p.x*planCanvas.width/planImage.width,p.y*planCanvas.height/planImage.height,5,0,Math.PI*2);ctx.fill();}dialog.querySelector('#plan-status').textContent=`Точек: ${points.length}/2 · масштаб ${draft.planImage.mmPerPixel.toFixed(2)} мм/пиксель`;}
const oldSurface=scene.onSurface;scene.onSurface=key=>{if(key.startsWith('wall-')){button.click();dialog.querySelector(`[data-wall="${Number(key.slice(5))}"]`)?.scrollIntoView({block:'center'});}else oldSurface(key);};
button.onclick=()=>{draft=structuredClone(getProject().room);draft.openings=effectiveOpenings(draft);draft.window=false;draft.door=false;points=[];render();dialog.showModal();};dialog.onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close'))dialog.close();if(b.dataset.shape){read();const w=draft.width/2,d=draft.depth/2;draft.vertices=b.dataset.shape==='rectangle'?null:[{x:-w,z:-d},{x:w,z:-d},{x:w,z:0},{x:0,z:0},{x:0,z:d},{x:-w,z:d}];render();}if(b.hasAttribute('data-preview')){read();preview();}if(b.dataset.add){read();const k=b.dataset.add;draft[k].push(k==='openings'?{id:crypto.randomUUID(),wallIndex:0,type:'window',offset:100,width:1000,height:1000,sill:1000,open:0}:k==='obstacles'?{id:crypto.randomUUID(),type:'column',x:0,z:0,width:400,depth:400,height:draft.height,rotation:0}:{id:crypto.randomUUID(),type:'socket',label:'Розетка',x:0,y:900,z:0,width:80,height:80,depth:40});render();}if(b.dataset.remove){read();const [k,i]=b.dataset.remove.split(':');draft[k].splice(+i,1);render();}if(b.id==='plan-calibrate'){if(points.length!==2)throw Error('Отметьте две точки на плане');const c=calibratePlan(points[0],points[1],+dialog.querySelector('[data-field="distance"]').value);draft.planImage.mmPerPixel=c.mmPerPixel;drawPlan();}if(b.id==='plan-clear'){draft.planImage=null;points=[];render();}if(b.id==='room-pro-apply'){read();if(!preview())return;if(draft.planImage)for(const k of ['offsetX','offsetZ','rotation','opacity'])draft.planImage[k]=+dialog.querySelector(`[data-field="${k}"]`).value;const xs=draft.vertices.map(p=>p.x),zs=draft.vertices.map(p=>p.z);draft.width=Math.max(1500,Math.max(...xs)-Math.min(...xs));draft.depth=Math.max(1500,Math.max(...zs)-Math.min(...zs));getProject().room=normalizeRoom(draft);commit({rebuild:true});dialog.close();toast('Помещение обновлено');}}catch(err){dialog.querySelector('#room-pro-error').textContent=err.message;}};
dialog.addEventListener('change',e=>{if(e.target.id!=='plan-upload')return;const f=e.target.files[0];if(!f)return;if(f.size>10000000||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('План: PNG/JPEG/WebP до 10 МБ');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),k=Math.min(1,1200/Math.max(img.width,img.height));c.width=img.width*k;c.height=img.height*k;c.getContext('2d').drawImage(img,0,0,c.width,c.height);draft.planImage={src:c.toDataURL('image/jpeg',.8),visible:true,opacity:.45,mmPerPixel:5,offsetX:0,offsetZ:0,rotation:0};points=[];loadImage(draft.planImage.src);};img.src=reader.result;};reader.readAsDataURL(f);});dialog.addEventListener('click',e=>{if(e.target.id!=='plan-canvas'||!planImage)return;const rect=planCanvas.getBoundingClientRect();if(points.length===2)points=[];points.push({x:(e.clientX-rect.left)*planImage.width/rect.width,y:(e.clientY-rect.top)*planImage.height/rect.height});drawPlan();});return {render(){}};}
